fn start_running_uses_injected_factory() {
    use std::sync::atomic::{AtomicBool, Ordering};

    struct SpyFactory {
        called: AtomicBool,
    }

    impl ProgressFactory for SpyFactory {
        fn create_spinner(&self, _prefix: &str, message: &str) -> indicatif::ProgressBar {
            self.called.store(true, Ordering::SeqCst);
            let bar = indicatif::ProgressBar::hidden();
            bar.set_message(message.to_string());
            bar
        }

        fn create_progress_bar(
            &self,
            _total: u64,
            msg: String,
        ) -> indicatif::ProgressBar {
            let bar = indicatif::ProgressBar::hidden();
            bar.set_message(msg);
            bar
        }
    }

    let spy = Arc::new(SpyFactory {
        called: AtomicBool::new(false),
    });
    let surface = TerminalSurface::hidden();
    let mut s = TerminalStepDisplay::new(
        surface,
        OutputMode::Normal,
        0,
        3,
        Arc::clone(&spy) as Arc<dyn ProgressFactory>,
        test_prompter(),
    );
    s.start_running("echo hello");
    assert!(spy.called.load(Ordering::SeqCst));
    assert!(s.region.is_some());
}

