mod tests {
    use super::*;

    fn header() -> RunHeader {
        RunHeader {
            app_name: "Test".to_string(),
            version: "1.0.0".to_string(),
            workflow: "default".to_string(),
            step_count: 3,
            env_name: "development".to_string(),
