        let mut wd = TerminalWorkflowDisplay::new(surface, OutputMode::Normal);
        let summary = RunSummary {
            step_results: vec![],
            total_duration: Duration::from_secs(2),
            steps_run: 2,
            steps_skipped: 0,
            steps_satisfied: 0,
            success: true,
            failed_steps: vec![],
        };
        wd.show_run_summary(&summary);
    }

