//! Progress indicator factory abstraction.
//!
//! [`ProgressFactory`] decouples the runner display layer from direct
//! `indicatif` construction. Production code uses
//! [`TerminalProgressFactory`] (styled spinners and bars); tests use
//! [`HiddenProgressFactory`] (hidden, no-op bars).

use std::time::Duration;

use indicatif::{ProgressBar, ProgressStyle};

/// Factory for creating `indicatif` progress indicators.
///
/// Decouples runner display implementations from direct `indicatif`
/// construction so tests can substitute hidden or no-op bars without
/// touching terminal state.
pub trait ProgressFactory {
    /// Create a spinner for step execution progress.
    ///
    /// `prefix` is prepended to the spinner template (typically
    /// whitespace for indentation). `message` is the initial spinner
    /// text (e.g. `"Running \`cmd\`..."`).
    fn create_spinner(&self, prefix: &str, message: &str) -> ProgressBar;

    /// Create a progress bar for workflow completion tracking.
    ///
    /// `total` is the number of steps. `initial_message` is the
    /// formatted bar text shown at position 0/total.
    fn create_progress_bar(&self, total: u64, initial_message: String) -> ProgressBar;
}

/// Terminal progress factory that creates styled progress indicators.
///
/// Produces spinners with braille tick characters and magenta coloring,
/// and workflow progress bars with a `{msg}` template. These match the
/// visual style previously hardcoded in the display layer.
pub struct TerminalProgressFactory;

impl ProgressFactory for TerminalProgressFactory {
    fn create_spinner(&self, prefix: &str, message: &str) -> ProgressBar {
        let bar = ProgressBar::new_spinner();
        bar.set_style(
            ProgressStyle::default_spinner()
                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
                .unwrap(),
        );
        bar.set_message(message.to_string());
        bar.enable_steady_tick(Duration::from_millis(80));
        bar
    }

    fn create_progress_bar(&self, total: u64, initial_message: String) -> ProgressBar {
        let bar = ProgressBar::new(total);
        bar.set_style(ProgressStyle::default_bar().template("{msg}").unwrap());
        bar.set_message(initial_message);
        bar
    }
}

/// Hidden progress factory for testing.
///
/// Creates hidden progress bars that produce no terminal output,
/// suitable for unit tests and non-interactive environments.
pub struct HiddenProgressFactory;

impl ProgressFactory for HiddenProgressFactory {
    fn create_spinner(&self, _prefix: &str, message: &str) -> ProgressBar {
        let bar = ProgressBar::hidden();
        bar.set_message(message.to_string());
        bar
    }

    fn create_progress_bar(&self, _total: u64, initial_message: String) -> ProgressBar {
        let bar = ProgressBar::hidden();
        bar.set_message(initial_message);
        bar
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn terminal_factory_spinner_sets_message() {
        let factory = TerminalProgressFactory;
        let bar = factory.create_spinner("  ", "Running test...");
        assert_eq!(bar.message(), "Running test...");
        assert!(!bar.is_hidden());
    }

    #[test]
    fn terminal_factory_progress_bar_sets_message() {
        let factory = TerminalProgressFactory;
        let bar = factory.create_progress_bar(10, "Progress...".to_string());
        assert_eq!(bar.message(), "Progress...");
        assert!(!bar.is_hidden());
    }

    #[test]
    fn hidden_factory_creates_hidden_spinner() {
        let factory = HiddenProgressFactory;
        let bar = factory.create_spinner("  ", "hidden spinner");
        assert!(bar.is_hidden());
        assert_eq!(bar.message(), "hidden spinner");
    }

    #[test]
    fn hidden_factory_creates_hidden_progress_bar() {
        let factory = HiddenProgressFactory;
        let bar = factory.create_progress_bar(5, "hidden bar".to_string());
        assert!(bar.is_hidden());
        assert_eq!(bar.message(), "hidden bar");
    }

    #[test]
    fn terminal_factory_is_object_safe() {
        let factory: Box<dyn ProgressFactory> = Box::new(TerminalProgressFactory);
        let _ = factory;
    }

    #[test]
    fn hidden_factory_is_object_safe() {
        let factory: Box<dyn ProgressFactory> = Box::new(HiddenProgressFactory);
        let _ = factory;
    }
}

